ASSETS = {'wudu_leftarm': '', 'male_intention': '', 'wudu_hands': '', 'female_sujud': '', 'wudu_feet': '', 'female_bowing': '', 'male_standing': '', 'wudu_mouth': '', 'female_intention': '', 'wudu_intention': '', 'male_final_sitting': '', 'female_upright': '', 'wudu_head': '', 'wudu_nose': '', 'wudu_face': '', 'female_final_sitting': '', 'male_upright': '', 'male_sujud': '', 'male_takbir': '', 'male_bowing': '', 'female_takbir': '', 'wudu_rightarm': '', 'wudu_ears': '', 'male_sitting': '', 'female_sitting': '', 'female_standing': ''}

BLOCK = '// MARK: - Prayer guide\n\nprivate enum PrayerPose: String {\n    case intention, takbir, standing, bowing, upright, prostration, sitting, finalSitting, salam\n}\n\nprivate struct PrayerRecitation: Identifiable {\n    let id = UUID()\n    let deLabel: String\n    let trLabel: String\n    let arabic: String\n    let transliteration: String\n    let deMeaning: String\n    let trMeaning: String\n    let deNote: String?\n    let trNote: String?\n}\n\nprivate struct PrayerTutorialStep: Identifiable {\n    let id = UUID()\n    let number: String\n    let pose: PrayerPose\n    let imageKey: String?\n    let deTitle: String\n    let trTitle: String\n    let deAction: String\n    let trAction: String\n    let deHanafi: String?\n    let trHanafi: String?\n    let recitations: [PrayerRecitation]\n}\n\nprivate enum PrayerText {\n    static let takbir = PrayerRecitation(\n        deLabel: "Beim Beginn / beim Übergang", trLabel: "Başlarken / geçişte",\n        arabic: "اللّٰهُ أَكْبَرُ", transliteration: "Allāhu akbar",\n        deMeaning: "Allah ist größer / der Größte.", trMeaning: "Allah en büyüktür.",\n        deNote: nil, trNote: nil)\n\n    static let subhanaka = PrayerRecitation(\n        deLabel: "Sübhaneke", trLabel: "Sübhâneke",\n        arabic: "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ وَتَبَارَكَ اسْمُكَ وَتَعَالَى جَدُّكَ وَلَا إِلٰهَ غَيْرُكَ",\n        transliteration: "Sübhâneke Allâhümme ve bi hamdik. Ve tebârekesmük. Ve teâlâ ceddük. Ve lâ ilâhe ğayrük.",\n        deMeaning: "Gepriesen bist Du, o Allah, und Dir gebührt Lob. Gesegnet ist Dein Name, erhaben ist Deine Majestät, und es gibt keinen Gott außer Dir.",\n        trMeaning: "Allah\'ım! Sen eksik sıfatlardan uzaksın. Seni överim. Senin adın mübarektir, şanın yücedir. Senden başka ilâh yoktur.",\n        deNote: "Im ersten Rakʿah nach dem Eröffnungstakbir.", trNote: "İlk rekâtta iftitah tekbirinden sonra.")\n\n    static let audhu = PrayerRecitation(\n        deLabel: "Eʿūḏu", trLabel: "Eûzü",\n        arabic: "أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ", transliteration: "Eʿûzü billâhi mineş-şeytânirracîm",\n        deMeaning: "Ich suche Zuflucht bei Allah vor dem verfluchten Satan.", trMeaning: "Kovulmuş şeytandan Allah\'a sığınırım.",\n        deNote: "Im ersten Rakʿah vor der Fātiha.", trNote: "İlk rekâtta Fâtiha\'dan önce.")\n\n    static let basmala = PrayerRecitation(\n        deLabel: "Basmala", trLabel: "Besmele",\n        arabic: "بِسْمِ اللَّهِ الرَّحْمٰنِ الرَّحِيمِ", transliteration: "Bismillâhirrahmânirrahîm",\n        deMeaning: "Im Namen Allahs, des Allerbarmers, des Barmherzigen.", trMeaning: "Rahmân ve Rahîm olan Allah\'ın adıyla.",\n        deNote: nil, trNote: nil)\n\n    static let fatiha = PrayerRecitation(\n        deLabel: "Al-Fātiha", trLabel: "Fâtiha Sûresi",\n        arabic: "الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ\\nالرَّحْمٰنِ الرَّحِيمِ\\nمَالِكِ يَوْمِ الدِّينِ\\nإِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ\\nاهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ\\nصِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ",\n        transliteration: "Elhamdülillâhi rabbil âlemîn. Errahmânirrahîm. Mâliki yevmiddîn. İyyâke na\'büdü ve iyyâke neste\'în. İhdinessırâtal müstakîm. Sırâtallezîne en\'amte aleyhim ğayril mağdûbi aleyhim ve leddâllîn. Âmîn.",\n        deMeaning: "Die eröffnende Sura. In jedem Rakʿah wird al-Fātiha rezitiert; nach ihrem Ende sagt man Âmîn.",\n        trMeaning: "Açılış sûresi. Her rekâtta Fâtiha okunur; sonunda Âmin denir.",\n        deNote: "Für den Wortlaut und Audio kannst du zusätzlich den Quran-Bereich öffnen.", trNote: "Metin ve ses için ayrıca Kur\'an bölümünü açabilirsin.")\n\n    static let ikhlas = PrayerRecitation(\n        deLabel: "Beispiel Zusatzsura: Al-Ikhlāṣ", trLabel: "Örnek zamm-ı sûre: İhlâs",\n        arabic: "قُلْ هُوَ اللَّهُ أَحَدٌ\\nاللَّهُ الصَّمَدُ\\nلَمْ يَلِدْ وَلَمْ يُولَدْ\\nوَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ",\n        transliteration: "Kul hüvallâhü ehad. Allâhüssamed. Lem yelid ve lem yûled. Ve lem yekün lehû küfüven ehad.",\n        deMeaning: "Sprich: Er ist Allah, der Eine …", trMeaning: "De ki: O Allah birdir …",\n        deNote: "Nur ein Beispiel. Eine andere passende Sura oder Quranverse sind ebenfalls möglich.", trNote: "Sadece örnektir. Başka uygun bir sûre veya ayetler de okunabilir.")\n\n    static let ruku = PrayerRecitation(\n        deLabel: "Im Rukūʿ", trLabel: "Rükûda",\n        arabic: "سُبْحَانَ رَبِّيَ الْعَظِيمِ", transliteration: "Sübhâne rabbiyel-azîm (3×)",\n        deMeaning: "Gepriesen sei mein gewaltiger Herr.", trMeaning: "Yüce Rabbimi noksan sıfatlardan tenzih ederim.", deNote: nil, trNote: nil)\n\n    static let rising = PrayerRecitation(\n        deLabel: "Beim Aufrichten", trLabel: "Doğrulurken",\n        arabic: "سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ", transliteration: "Semi\'allāhu limen hamideh",\n        deMeaning: "Allah hört den, der Ihn lobt.", trMeaning: "Allah kendisine hamd edeni işitir.",\n        deNote: "Hanafi: Imam und allein Betender sagen dies beim Aufrichten.", trNote: "Hanefî: İmam ve yalnız kılan doğrulurken bunu söyler.")\n\n    static let upright = PrayerRecitation(\n        deLabel: "Vollständig aufgerichtet", trLabel: "Tam doğrulunca",\n        arabic: "رَبَّنَا لَكَ الْحَمْدُ", transliteration: "Rabbenâ lekel-hamd",\n        deMeaning: "Unser Herr, Dir gebührt das Lob.", trMeaning: "Rabbimiz, hamd Sana mahsustur.",\n        deNote: "Hanafi: Der Mitbetende hinter dem Imam sagt dies; der allein Betende ebenfalls nach dem Aufrichten.", trNote: "Hanefî: İmama uyan bunu söyler; yalnız kılan da doğrulunca söyler.")\n\n    static let sujud = PrayerRecitation(\n        deLabel: "In der Secde", trLabel: "Secdede",\n        arabic: "سُبْحَانَ رَبِّيَ الْأَعْلَى", transliteration: "Sübhâne rabbiyel-a\'lâ (3×)",\n        deMeaning: "Gepriesen sei mein höchster Herr.", trMeaning: "Yüce Rabbimi noksan sıfatlardan tenzih ederim.", deNote: nil, trNote: nil)\n\n    static let rabbighfirli = PrayerRecitation(\n        deLabel: "Mögliche Dua zwischen den Secden", trLabel: "İki secde arasında okunabilecek dua",\n        arabic: "رَبِّ اغْفِرْ لِي", transliteration: "Rabbighfir lī",\n        deMeaning: "Mein Herr, vergib mir.", trMeaning: "Rabbim, beni bağışla.",\n        deNote: "Keine Pflichtformel; die kurze ruhige Sitzphase selbst soll nicht ausgelassen werden.", trNote: "Zorunlu bir söz değildir; kısa ve sakin oturuş atlanmamalıdır.")\n\n    static let tahiyyat = PrayerRecitation(\n        deLabel: "Ettehiyyâtü / Tashahhud", trLabel: "Ettehiyyâtü / Tahiyyat",\n        arabic: "التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ",\n        transliteration: "Ettehiyyâtü lillâhi vessalevâtü vettayyibât. Esselâmü aleyke eyyühen-nebiyyü ve rahmetullâhi ve berekâtüh. Esselâmü aleynâ ve alâ ibâdillâhis-sâlihîn. Eşhedü en lâ ilâhe illallâh ve eşhedü enne Muhammeden abdühû ve resûlüh.",\n        deMeaning: "Die Grüße, Gebete und guten Dinge gehören Allah … Ich bezeuge, dass es keinen Gott außer Allah gibt und dass Muhammad Sein Diener und Gesandter ist.",\n        trMeaning: "Bütün hürmetler, dualar ve güzel sözler Allah\'a mahsustur … Allah\'tan başka ilâh olmadığına ve Muhammed\'in O\'nun kulu ve elçisi olduğuna şahitlik ederim.", deNote: nil, trNote: nil)\n\n    static let salli = PrayerRecitation(\n        deLabel: "Allahümme Salli", trLabel: "Allâhümme Salli",\n        arabic: "اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ",\n        transliteration: "Allâhümme salli alâ Muhammedin ve alâ âli Muhammed. Kemâ salleyte alâ İbrâhîme ve alâ âli İbrâhîm. İnneke hamîdün mecîd.",\n        deMeaning: "O Allah, segne Muhammad und die Familie Muhammads, wie Du Ibrahim und die Familie Ibrahims gesegnet hast. Du bist der Lobenswerte, der Ruhmreiche.",\n        trMeaning: "Allah\'ım, İbrahim\'e ve ailesine rahmet ettiğin gibi Muhammed\'e ve ailesine de rahmet et. Şüphesiz Sen övülmeye lâyık ve şan sahibisin.", deNote: nil, trNote: nil)\n\n    static let barik = PrayerRecitation(\n        deLabel: "Allahümme Bârik", trLabel: "Allâhümme Bârik",\n        arabic: "اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ",\n        transliteration: "Allâhümme bârik alâ Muhammedin ve alâ âli Muhammed. Kemâ bârekte alâ İbrâhîme ve alâ âli İbrâhîm. İnneke hamîdün mecîd.",\n        deMeaning: "O Allah, schenke Muhammad und der Familie Muhammads Segen, wie Du Ibrahim und der Familie Ibrahims Segen geschenkt hast.",\n        trMeaning: "Allah\'ım, İbrahim\'e ve ailesine bereket verdiğin gibi Muhammed\'e ve ailesine de bereket ver.", deNote: nil, trNote: nil)\n\n    static let rabbana = PrayerRecitation(\n        deLabel: "Rabbenâ Âtinâ", trLabel: "Rabbenâ Âtinâ",\n        arabic: "رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ",\n        transliteration: "Rabbenâ âtinâ fid-dünyâ haseneten ve fil-âhireti haseneten ve kınâ azâben-nâr.",\n        deMeaning: "Unser Herr, gib uns Gutes im Diesseits und Gutes im Jenseits und bewahre uns vor der Strafe des Feuers.",\n        trMeaning: "Rabbimiz, bize dünyada da iyilik, ahirette de iyilik ver ve bizi ateş azabından koru.", deNote: "Quran 2:201", trNote: "Kur\'an 2:201")\n\n    static let salam = PrayerRecitation(\n        deLabel: "Rechts und anschließend links", trLabel: "Önce sağa, sonra sola",\n        arabic: "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", transliteration: "Es-selâmü aleyküm ve rahmetullâh",\n        deMeaning: "Friede und Allahs Barmherzigkeit seien mit euch.", trMeaning: "Allah\'ın selâmı ve rahmeti üzerinize olsun.",\n        deNote: "Den Satz einmal beim Drehen nach rechts und danach erneut beim Drehen nach links sprechen.", trNote: "Cümleyi önce sağa dönerken, sonra sola dönerken tekrar söyle.")\n}\n\nstruct PrayerHowToView: View {\n    @EnvironmentObject private var settings: SettingsStore\n\n    private var steps: [PrayerTutorialStep] {\n        [\n            .init(number: "1", pose: .intention, imageKey: "intention", deTitle: "Niyyah – Absicht", trTitle: "Niyet", deAction: "Stehe sauber bedeckt und zur Qibla. Fasse im Herzen die Absicht für genau das Gebet, das du jetzt betest. Eine bestimmte gesprochene Niyyah-Formel ist nicht erforderlich.", trAction: "Temiz ve örtülü şekilde kıbleye dön. Kılacağın namaza kalben niyet et. Niyeti belirli bir cümleyle sesli söylemek şart değildir.", deHanafi: nil, trHanafi: nil, recitations: []),\n            .init(number: "2", pose: .takbir, imageKey: "takbir", deTitle: "Eröffnungstakbir", trTitle: "İftitah tekbiri", deAction: "Heb beide Hände an und sage einmal Allāhu akbar. Danach die Hände für den Qiyām binden.", trAction: "İki eli kaldır, bir kez Allāhu ekber de. Sonra kıyam için elleri bağla.", deHanafi: settings.prayerAudience == .male ? "Hanafi Mann: Daumen etwa auf Höhe der Ohrläppchen." : "Hanafi Frau: Fingerspitzen etwa bis Schulterhöhe.", trHanafi: settings.prayerAudience == .male ? "Hanefî erkek: Başparmaklar yaklaşık kulak memesi hizasında." : "Hanefî kadın: Parmak uçları yaklaşık omuz hizasına kadar.", recitations: [.init(deLabel: "Einmal", trLabel: "Bir kez", arabic: PrayerText.takbir.arabic, transliteration: PrayerText.takbir.transliteration, deMeaning: PrayerText.takbir.deMeaning, trMeaning: PrayerText.takbir.trMeaning, deNote: nil, trNote: nil)]),\n            .init(number: "3", pose: .standing, imageKey: "standing", deTitle: "Qiyām – Hände binden", trTitle: "Kıyam – elleri bağlama", deAction: "Stehe ruhig und schaue zum Ort der Niederwerfung. Beginne im ersten Rakʿah mit Sübhaneke.", trAction: "Sakin dur ve secde edeceğin yere bak. İlk rekâtta Sübhâneke ile başla.", deHanafi: settings.prayerAudience == .male ? "Mann: rechte Hand über die linke unterhalb des Nabels; rechte Hand umfasst das linke Handgelenk." : "Frau: rechte Hand über die linke auf der Brust; Handgelenk nicht wie beim Mann umfassen.", trHanafi: settings.prayerAudience == .male ? "Erkek: sağ el sol elin üzerinde, göbek altında; sağ el sol bileği kavrar." : "Kadın: sağ el sol elin üzerinde göğüs üstünde; bilek erkeklerdeki gibi kavranmaz.", recitations: [PrayerText.subhanaka]),\n            .init(number: "4", pose: .standing, imageKey: "standing", deTitle: "Qiyām – Quran rezitieren", trTitle: "Kıyam – kıraat", deAction: "Im ersten Rakʿah: Eʿūḏu, Basmala, al-Fātiha, Âmîn und anschließend eine zusätzliche Sura oder passende Verse. Im zweiten Rakʿah beginnt man mit der Basmala, dann Fātiha und Zusatzsura.", trAction: "İlk rekâtta: Eûzü, Besmele, Fâtiha, Âmin ve ardından zamm-ı sûre veya uygun ayetler. İkinci rekâtta Besmele, Fâtiha ve zamm-ı sûre okunur.", deHanafi: "Bei 3-/4-Rakʿah-Fard wird im 3. und 4. Rakʿah nach hanafitischer Lehre grundsätzlich nur al-Fātiha gelesen. Vier-Rakʿah-Sunnah hat eigene Regeln – siehe Gebetsplan.", trHanafi: "3/4 rekât farz namazların 3. ve 4. rekâtında Hanefî uygulamada esas olarak yalnız Fâtiha okunur. Dört rekât sünnetlerin ayrıntısı için namaz planına bak.", recitations: [PrayerText.audhu, PrayerText.basmala, PrayerText.fatiha, PrayerText.ikhlas]),\n            .init(number: "5", pose: .bowing, imageKey: "bowing", deTitle: "Rukūʿ", trTitle: "Rükû", deAction: "Sage beim Hinuntergehen Allāhu akbar. Beuge dich und halte die Position kurz ruhig. Danach den Rukūʿ-Dhikr dreimal.", trAction: "Rükûya giderken Allāhu ekber de. Rükûda kısa bir an sakin dur. Sonra rükû tesbihini üç kez söyle.", deHanafi: settings.prayerAudience == .male ? "Mann: Rücken möglichst gerade, Hände auf den Knien, Knie gestreckt." : "Frau: kompaktere Haltung; Rücken weniger waagerecht, Hände auf den Knien, Knie etwas gebeugt.", trHanafi: settings.prayerAudience == .male ? "Erkek: sırt mümkün olduğunca düz, eller dizlerde, dizler dik." : "Kadın: daha toplu duruş; sırt daha az yatay, eller dizlerde, dizler biraz bükülü.", recitations: [PrayerText.takbir, PrayerText.ruku]),\n            .init(number: "6", pose: .upright, imageKey: "upright", deTitle: "Kavme – vollständig aufrichten", trTitle: "Kavme – rükûdan tam doğrulma", deAction: "Richte dich vollständig aus dem Rukūʿ auf. Nicht direkt in die Secde fallen: erst ganz stehen und kurz ruhig werden.", trAction: "Rükûdan tamamen doğrul. Hemen secdeye inme; önce tam ayağa kalk ve kısa bir an sakin dur.", deHanafi: "Allein/Imam: beim Hochkommen Semi\'allāhu limen hamideh; vollständig stehend Rabbenâ lekel-hamd. Hinter dem Imam: Rabbenâ lekel-hamd.", trHanafi: "Yalnız/İmam: doğrulurken Semi\'allāhu limen hamideh; tam doğrulunca Rabbenâ lekel-hamd. İmama uyan: Rabbenâ lekel-hamd.", recitations: [PrayerText.rising, PrayerText.upright]),\n            .init(number: "7", pose: .prostration, imageKey: "sujud", deTitle: "Erste Secde", trTitle: "Birinci secde", deAction: "Sage Allāhu akbar und gehe in die Niederwerfung. Stirn und Nase liegen auf; Hände stehen neben dem Kopf. Halte die Secde ruhig und sage den Dhikr dreimal.", trAction: "Allāhu ekber diyerek secdeye git. Alın ve burun yere gelir; eller başın yanında olur. Secdede sakin dur ve tesbihi üç kez söyle.", deHanafi: settings.prayerAudience == .male ? "Mann: Unterarme vom Boden und Arme vom Körper fernhalten, sofern ohne Mühe möglich." : "Frau: Arme näher am Körper, Bauch näher an den Oberschenkeln; kompaktere Haltung.", trHanafi: settings.prayerAudience == .male ? "Erkek: mümkünse dirsekleri yere koymaz, kolları gövdeden açık tutar." : "Kadın: kollar gövdeye, karın uyluklara daha yakın; daha toplu duruş.", recitations: [PrayerText.takbir, PrayerText.sujud]),\n            .init(number: "8", pose: .sitting, imageKey: "sitting", deTitle: "Celse – zwischen den Secden", trTitle: "Celse – iki secde arası", deAction: "Sage Allāhu akbar und setze dich vollständig auf. Bleibe kurz ruhig sitzen; dann erst zur zweiten Secde.", trAction: "Allāhu ekber diyerek tamamen otur. Kısa bir an sakin otur; sonra ikinci secdeye git.", deHanafi: settings.prayerAudience == .male ? "Mann: auf dem linken Fuß sitzen; rechter Fuß aufgestellt, Zehen Richtung Qibla." : "Frau: beide Füße zur rechten Seite herausnehmen und auf dem Boden sitzen.", trHanafi: settings.prayerAudience == .male ? "Erkek: sol ayak üzerine oturur; sağ ayak dik, parmaklar kıbleye yönelir." : "Kadın: iki ayağını sağ tarafa çıkararak yere oturur.", recitations: [PrayerText.takbir, PrayerText.rabbighfirli]),\n            .init(number: "9", pose: .prostration, imageKey: "sujud", deTitle: "Zweite Secde", trTitle: "İkinci secde", deAction: "Sage Allāhu akbar, gehe erneut in die Secde und sprich den Dhikr dreimal. Danach mit Allāhu akbar zum nächsten Rakʿah aufstehen oder – wenn vorgeschrieben – sitzen bleiben.", trAction: "Allāhu ekber diyerek tekrar secdeye git ve tesbihi üç kez söyle. Sonra Allāhu ekber diyerek sonraki rekâta kalk veya gerekiyorsa otur.", deHanafi: nil, trHanafi: nil, recitations: [PrayerText.takbir, PrayerText.sujud]),\n            .init(number: "10", pose: .sitting, imageKey: "final_sitting", deTitle: "Nach dem 2. Rakʿah", trTitle: "2. rekâttan sonra", deAction: "Nach zwei Rakʿah sitzt du und liest Ettehiyyâtü. Endet das Gebet hier, folgt das vollständige Schluss-Sitzen. Geht ein 3-/4-Rakʿah-Fard weiter, stehst du nach Ettehiyyâtü mit Allāhu akbar auf.", trAction: "İki rekâttan sonra oturup Ettehiyyâtü oku. Namaz burada bitiyorsa son oturuşa devam edilir. 3/4 rekât farz devam ediyorsa Ettehiyyâtü\'den sonra Allāhu ekber diyerek ayağa kalkılır.", deHanafi: "Bei bestimmten vier-Rakʿah-Sunnah-Gebeten ist die erste Sitzphase anders – im Gebetsplan wird das getrennt erklärt.", trHanafi: "Bazı dört rekât sünnetlerde ilk oturuş farklıdır; namaz planında ayrı açıklanır.", recitations: [PrayerText.tahiyyat]),\n            .init(number: "11", pose: .finalSitting, imageKey: "final_sitting", deTitle: "Letztes Sitzen", trTitle: "Son oturuş", deAction: "Im letzten Sitzen: Ettehiyyâtü, anschließend Allahümme Salli, Allahümme Bârik und eine Abschlussdua wie Rabbenâ Âtinâ.", trAction: "Son oturuşta: Ettehiyyâtü, ardından Allâhümme Salli, Allâhümme Bârik ve Rabbenâ Âtinâ gibi bir kapanış duası okunur.", deHanafi: nil, trHanafi: nil, recitations: [PrayerText.tahiyyat, PrayerText.salli, PrayerText.barik, PrayerText.rabbana]),\n            .init(number: "12", pose: .salam, imageKey: nil, deTitle: "Salām – Gebet beenden", trTitle: "Selâm – namazı bitirme", deAction: "Das ist bewusst in zwei klare Bewegungen geteilt: zuerst Gesicht nach RECHTS und den Satz sprechen; danach Gesicht nach LINKS und denselben Satz erneut sprechen.", trAction: "Bu adım iki açık harekete ayrılır: önce yüzünü SAĞA çevirip cümleyi söyle; sonra SOLA çevirip aynı cümleyi tekrar söyle.", deHanafi: "Hanafi: zuerst rechts, dann links. Kein Kreis drehen – nur den Kopf/das Gesicht jeweils zur Seite wenden.", trHanafi: "Hanefî: önce sağa, sonra sola. Daire çizilmez; sadece baş/yüz iki yana çevrilir.", recitations: [PrayerText.salam])\n        ]\n    }\n\n    var body: some View {\n        ScrollView {\n            LazyVStack(spacing: 14) {\n                VStack(alignment: .leading, spacing: 10) {\n                    HStack {\n                        Label(settings.t("Hanafi · Türkei Lernmodus", "Hanefî · Türkiye öğrenme modu"), systemImage: "checkmark.seal.fill")\n                            .font(.headline)\n                        Spacer()\n                    }\n                    Picker(settings.t("Anleitung für", "Anlatım"), selection: $settings.prayerAudience) {\n                        ForEach(PrayerAudience.allCases) { audience in\n                            Text(audience.title(settings.language)).tag(audience)\n                        }\n                    }\n                    .pickerStyle(.segmented)\n                    Text(settings.t("Die App trennt Handlung und gesprochenen Text. Übergangs-Takbīre stehen dort, wo sie gesagt werden. Abweichungen anderer Rechtsschulen werden nicht als Fehler bezeichnet.", "Uygulama hareket ile okunan sözü ayırır. Geçiş tekbirleri söylendikleri yerde gösterilir. Diğer mezheplerin farklı uygulamaları hata sayılmaz."))\n                        .font(.footnote)\n                        .foregroundStyle(.secondary)\n                }\n                .cardStyle(material: true)\n\n                NavigationLink { HanafiPrayerPlanView() } label: {\n                    HStack {\n                        Label(settings.t("2, 3, 4 Rakʿah & Witr genau", "2, 3, 4 rekât ve vitir ayrıntılı"), systemImage: "list.number")\n                            .font(.headline)\n                        Spacer(); Image(systemName: "chevron.right")\n                    }\n                    .cardStyle()\n                }\n                .buttonStyle(.plain)\n\n                ForEach(steps) { step in\n                    PrayerTutorialStepCard(step: step, audience: settings.prayerAudience)\n                }\n\n                VStack(alignment: .leading, spacing: 8) {\n                    Text(settings.t("Quellen & Einordnung", "Kaynaklar ve açıklama")).font(.headline)\n                    Text(settings.t("Die Haltungsunterschiede Mann/Frau, Handhaltung, Rukūʿ, Secde und Sitzweise orientieren sich an der hanafitischen Darstellung des Diyanet Din İşleri Yüksek Kurulu. Tuma\'nīna/ta\'dīl-i erkān bedeutet, Rukūʿ, Kavme, Secde und Celse vollständig und ruhig auszuführen.", "Erkek/kadın duruş farkları, el bağlama, rükû, secde ve oturuş biçimleri Diyanet Din İşleri Yüksek Kurulu\'nun Hanefî anlatımına göre hazırlanmıştır. Tuma\'nîne/ta\'dîl-i erkân; rükû, kavme, secde ve celseyi tam ve sakin yapmaktır."))\n                        .font(.footnote).foregroundStyle(.secondary)\n                    Link("Diyanet · Kadın/erkek namaz farkları", destination: URL(string: "https://kurul.diyanet.gov.tr/tr/fetva/kilinis-bakimindan-kadinlarin-namazi-ile-erkeklerin-namazi/0193c42d-64a5-7ba1-9af3-f9f4a7f97245")!)\n                    Link("Diyanet · Ta\'dîl-i erkân", destination: URL(string: "https://kurul.diyanet.gov.tr/tr/fetva/namazda-tadil-i-erkanin-hukmu-nedir/0193c42d-4ed9-7a2a-78a0-a569a0ff598a")!)\n                    Link("Diyanet · Selâm", destination: URL(string: "https://kurul.diyanet.gov.tr/tr/fetva/namazdan-cikarken-verilen-selamin-hukmu-nedir/0193c42d-4f73-7e54-2687-55f6addfa71f")!)\n                }\n                .cardStyle(material: true)\n            }\n            .padding()\n        }\n        .navigationTitle(settings.t("Gebet komplett", "Namaz tamamen"))\n        .navigationBarTitleDisplayMode(.inline)\n    }\n}\n\nprivate struct PrayerTutorialStepCard: View {\n    @EnvironmentObject private var settings: SettingsStore\n    let step: PrayerTutorialStep\n    let audience: PrayerAudience\n\n    private var imageName: String? {\n        guard let key = step.imageKey else { return nil }\n        return "\\(audience == .male ? "male" : "female")_\\(key)"\n    }\n\n    var body: some View {\n        VStack(alignment: .leading, spacing: 12) {\n            HStack(alignment: .firstTextBaseline) {\n                Text(step.number)\n                    .font(.headline.bold())\n                    .frame(width: 32, height: 32)\n                    .background(Color.accentColor, in: Circle())\n                    .foregroundStyle(.white)\n                Text(settings.language == .german ? step.deTitle : step.trTitle)\n                    .font(.title3.bold())\n                Spacer()\n            }\n\n            if step.pose == .salam {\n                PrayerSalamVisual()\n            } else if let imageName {\n                Image(imageName)\n                    .resizable()\n                    .scaledToFit()\n                    .frame(maxWidth: .infinity)\n                    .frame(maxHeight: 255)\n                    .padding(8)\n                    .background(Color.secondary.opacity(0.055), in: RoundedRectangle(cornerRadius: 18))\n                    .accessibilityHidden(true)\n            }\n\n            VStack(alignment: .leading, spacing: 6) {\n                Label(settings.t("Was du machst", "Ne yaparsın"), systemImage: "figure.walk")\n                    .font(.subheadline.bold())\n                Text(settings.language == .german ? step.deAction : step.trAction)\n                    .font(.subheadline)\n            }\n\n            if let note = settings.language == .german ? step.deHanafi : step.trHanafi {\n                Label(note, systemImage: "info.circle.fill")\n                    .font(.caption)\n                    .foregroundStyle(.secondary)\n                    .padding(10)\n                    .frame(maxWidth: .infinity, alignment: .leading)\n                    .background(Color.accentColor.opacity(0.08), in: RoundedRectangle(cornerRadius: 12))\n            }\n\n            if !step.recitations.isEmpty {\n                Divider()\n                Label(settings.t("Was du sagst", "Ne söylersin"), systemImage: "text.bubble.fill")\n                    .font(.subheadline.bold())\n                ForEach(step.recitations) { rec in\n                    PrayerRecitationView(recitation: rec)\n                }\n            }\n        }\n        .cardStyle()\n    }\n}\n\nprivate struct PrayerRecitationView: View {\n    @EnvironmentObject private var settings: SettingsStore\n    let recitation: PrayerRecitation\n    @State private var showMeaning = false\n\n    var body: some View {\n        VStack(alignment: .leading, spacing: 7) {\n            Text(settings.language == .german ? recitation.deLabel : recitation.trLabel)\n                .font(.caption.bold())\n                .foregroundStyle(.secondary)\n            Text(recitation.arabic)\n                .font(.title3)\n                .multilineTextAlignment(.trailing)\n                .frame(maxWidth: .infinity, alignment: .trailing)\n            Text(recitation.transliteration)\n                .font(.subheadline.weight(.semibold))\n            Button(showMeaning ? settings.t("Bedeutung ausblenden", "Anlamı gizle") : settings.t("Bedeutung anzeigen", "Anlamı göster")) {\n                withAnimation(.easeInOut(duration: 0.2)) { showMeaning.toggle() }\n            }\n            .font(.caption)\n            if showMeaning {\n                Text(settings.language == .german ? recitation.deMeaning : recitation.trMeaning)\n                    .font(.footnote)\n                    .foregroundStyle(.secondary)\n            }\n            if let note = settings.language == .german ? recitation.deNote : recitation.trNote {\n                Text(note).font(.caption2).foregroundStyle(.tertiary)\n            }\n        }\n        .padding(10)\n        .background(Color.secondary.opacity(0.055), in: RoundedRectangle(cornerRadius: 12))\n    }\n}\n\nprivate struct PrayerSalamVisual: View {\n    @EnvironmentObject private var settings: SettingsStore\n    var body: some View {\n        HStack(spacing: 10) {\n            VStack(spacing: 8) {\n                Image(systemName: "arrow.right.circle.fill").font(.system(size: 38)).foregroundStyle(Color.accentColor)\n                Text(settings.t("1. RECHTS", "1. SAĞA")).font(.headline)\n                Text(settings.t("Gesicht nach rechts drehen", "Yüzünü sağa çevir")).font(.caption).multilineTextAlignment(.center)\n            }\n            .frame(maxWidth: .infinity)\n            .padding().background(Color.accentColor.opacity(0.08), in: RoundedRectangle(cornerRadius: 14))\n            VStack(spacing: 8) {\n                Image(systemName: "arrow.left.circle.fill").font(.system(size: 38)).foregroundStyle(Color.accentColor)\n                Text(settings.t("2. LINKS", "2. SOLA")).font(.headline)\n                Text(settings.t("Danach Gesicht nach links", "Sonra yüzünü sola çevir")).font(.caption).multilineTextAlignment(.center)\n            }\n            .frame(maxWidth: .infinity)\n            .padding().background(Color.accentColor.opacity(0.08), in: RoundedRectangle(cornerRadius: 14))\n        }\n        .accessibilityElement(children: .combine)\n    }\n}\n\nstruct HanafiPrayerPlanView: View {\n    @EnvironmentObject private var settings: SettingsStore\n\n    private struct PlanRow: Identifiable {\n        let id = UUID(); let de: String; let tr: String; let sequence: String; let deNote: String; let trNote: String\n    }\n\n    private let rows: [PlanRow] = [\n        .init(de: "Fajr", tr: "Sabah", sequence: "2 Sunnah → 2 Fard", deNote: "Die 2 Sunnah vor Fajr sind Sunnah mu\'akkadah.", trNote: "Farzdan önceki 2 rekât sünnet-i müekkededir."),\n        .init(de: "Dhuhr", tr: "Öğle", sequence: "4 Sunnah → 4 Fard → 2 Sunnah", deNote: "Die erste 4er-Sunnah und die 2 Sunnah danach sind in der hanafitischen Standarddarstellung besonders betonte Sunnah.", trNote: "Önceki 4 ve sonraki 2 rekât Hanefî anlatımda kuvvetli sünnetlerdendir."),\n        .init(de: "Asr", tr: "İkindi", sequence: "4 Sunnah → 4 Fard", deNote: "Die 4 Sunnah davor gelten als ghayr mu\'akkadah.", trNote: "Önceki 4 rekât sünnet gayr-i müekkededir."),\n        .init(de: "Maghrib", tr: "Akşam", sequence: "3 Fard → 2 Sunnah", deNote: "Nach den 3 Fard folgen 2 Sunnah.", trNote: "3 rekât farzdan sonra 2 rekât sünnet kılınır."),\n        .init(de: "Isha", tr: "Yatsı", sequence: "4 Sunnah → 4 Fard → 2 Sunnah → 3 Witr", deNote: "Die ersten 4 sind ghayr mu\'akkadah; die 2 danach mu\'akkadah. Witr ist im hanafitischen Fiqh wajib.", trNote: "İlk 4 gayr-i müekkede, sonraki 2 müekkede sünnettir. Vitir Hanefî fıkhında vaciptir.")\n    ]\n\n    var body: some View {\n        List {\n            Section(settings.t("Tagesplan", "Günlük plan")) {\n                ForEach(rows) { row in\n                    VStack(alignment: .leading, spacing: 5) {\n                        Text(settings.language == .german ? row.de : row.tr).font(.headline)\n                        Text(row.sequence).font(.subheadline.bold())\n                        Text(settings.language == .german ? row.deNote : row.trNote).font(.caption).foregroundStyle(.secondary)\n                    }.padding(.vertical, 4)\n                }\n            }\n\n            Section(settings.t("2 Rakʿah", "2 rekât")) {\n                Text(settings.t("1. Rakʿah vollständig → zweite Secde → mit Allāhu akbar aufstehen. 2. Rakʿah: Basmala, Fātiha + Zusatzsura → Rukūʿ → Kavme → 2 Secden → letztes Sitzen: Ettehiyyâtü + Salli + Bârik + Abschlussdua → Salām rechts und links.", "1. rekât tam olarak kılınır → ikinci secdeden sonra Allāhu ekber diyerek kalkılır. 2. rekât: Besmele, Fâtiha + zamm-ı sûre → rükû → kavme → 2 secde → son oturuş: Ettehiyyâtü + Salli + Bârik + kapanış duası → sağa ve sola selâm."))\n            }\n\n            Section(settings.t("3 Rakʿah Fard (Maghrib)", "3 rekât farz (Akşam)")) {\n                Text(settings.t("Nach dem 2. Rakʿah nur Ettehiyyâtü lesen und aufstehen. Im 3. Rakʿah Basmala + Fātiha; keine Zusatzsura erforderlich. Danach Rukūʿ, Kavme, 2 Secden und vollständiges letztes Sitzen.", "2. rekâttan sonra yalnız Ettehiyyâtü okunup ayağa kalkılır. 3. rekâtta Besmele + Fâtiha okunur; zamm-ı sûre gerekmez. Sonra rükû, kavme, 2 secde ve tam son oturuş yapılır."))\n            }\n\n            Section(settings.t("4 Rakʿah Fard", "4 rekât farz")) {\n                Text(settings.t("Nach dem 2. Rakʿah Ettehiyyâtü und aufstehen. Im 3. und 4. Rakʿah jeweils Basmala + Fātiha; keine Zusatzsura erforderlich. Nach dem 4. Rakʿah vollständiges letztes Sitzen und Salām.", "2. rekâttan sonra Ettehiyyâtü okunup kalkılır. 3. ve 4. rekâtta Besmele + Fâtiha okunur; zamm-ı sûre gerekmez. 4. rekâttan sonra tam son oturuş ve selâm yapılır."))\n            }\n\n            Section(settings.t("4 Rakʿah Sunnah", "4 rekât sünnet")) {\n                Text(settings.t("Bei vier Rakʿah Sunnah wird in allen Rakʿah Fātiha plus Zusatzsura gelesen. Bei der betonten 4er-Sunnah von Dhuhr liest man im ersten Sitzen Ettehiyyâtü und steht dann auf. Bei den 4 ghayr-mu\'akkadah vor Asr/Isha werden im ersten Sitzen zusätzlich Salli/Bârik gelesen; der 3. Rakʿah beginnt wieder mit Sübhaneke.", "Dört rekât sünnetlerde her rekâtta Fâtiha ve zamm-ı sûre okunur. Öğlenin kuvvetli 4 rekât sünnetinde ilk oturuşta Ettehiyyâtü okunup kalkılır. İkindi/yatsıdan önceki 4 gayr-i müekkede sünnette ilk oturuşta Salli/Bârik de okunur; 3. rekâta tekrar Sübhâneke ile başlanır."))\n            }\n\n            Section(settings.t("3 Rakʿah Witr", "3 rekât vitir")) {\n                Text(settings.t("Die ersten zwei Rakʿah wie ein 2-Rakʿah-Gebet, aber nach Ettehiyyâtü zum 3. Rakʿah aufstehen. Im 3. Rakʿah Basmala + Fātiha + Zusatzsura. Danach vor dem Rukūʿ erneut Allāhu akbar sagen, Hände heben, wieder binden und Qunūt-Duas lesen. Dann Rukūʿ, Kavme, 2 Secden, vollständiges letztes Sitzen und Salām.", "İlk iki rekât 2 rekât namaz gibi; Ettehiyyâtü\'den sonra 3. rekâta kalkılır. 3. rekâtta Besmele + Fâtiha + zamm-ı sûre okunur. Sonra rükûdan önce tekrar Allāhu ekber denir, eller kaldırılıp yeniden bağlanır ve Kunut duaları okunur. Ardından rükû, kavme, 2 secde, tam son oturuş ve selâm yapılır."))\n                NavigationLink { QunutDuaView() } label: { Label(settings.t("Qunūt-Duas vollständig", "Kunut duaları tam metin"), systemImage: "text.book.closed") }\n            }\n\n            Section {\n                Link("Diyanet · Namaz İlmihali", destination: URL(string: "https://dijital.diyanet.gov.tr/File/Download?id=394&path=namaz_ilmihali.pdf")!)\n            }\n        }\n        .navigationTitle(settings.t("Rakʿah-Ablauf", "Rekât düzeni"))\n    }\n}\n\nprivate struct QunutDuaView: View {\n    @EnvironmentObject private var settings: SettingsStore\n    var body: some View {\n        List {\n            Section("Kunut 1") {\n                Text("اللَّهُمَّ إِنَّا نَسْتَعِينُكَ وَنَسْتَغْفِرُكَ وَنَسْتَهْدِيكَ وَنُؤْمِنُ بِكَ وَنَتُوبُ إِلَيْكَ وَنَتَوَكَّلُ عَلَيْكَ وَنُثْنِي عَلَيْكَ الْخَيْرَ كُلَّهُ نَشْكُرُكَ وَلَا نَكْفُرُكَ وَنَخْلَعُ وَنَتْرُكُ مَنْ يَفْجُرُكَ").font(.title3).multilineTextAlignment(.trailing)\n                Text("Allâhümme innâ nesteînüke ve nestağfirüke ve nestehdîk. Ve nü\'minü bike ve netûbü ileyk. Ve netevekkelü aleyke ve nüsnî aleykel-hayra küllehû neşkürüke ve lâ nekfürük. Ve nahleu ve netrükü men yefcürük.")\n            }\n            Section("Kunut 2") {\n                Text("اللَّهُمَّ إِيَّاكَ نَعْبُدُ وَلَكَ نُصَلِّي وَنَسْجُدُ وَإِلَيْكَ نَسْعَى وَنَحْفِدُ نَرْجُو رَحْمَتَكَ وَنَخْشَى عَذَابَكَ إِنَّ عَذَابَكَ بِالْكُفَّارِ مُلْحِقٌ").font(.title3).multilineTextAlignment(.trailing)\n                Text("Allâhümme iyyâke na\'büdü ve leke nusallî ve nescüd. Ve ileyke nes\'â ve nahfid. Nercû rahmeteke ve nahşâ azâbek. İnne azâbeke bil-küffâri mülhik.")\n            }\n            Section {\n                Text(settings.t("Die in der Türkei verbreiteten hanafitischen Qunūt-Texte für Witr. Für Aussprachetraining sollte eine verlässliche menschliche Aufnahme verwendet werden; SalahPath erzeugt hierfür keine KI-Stimme.", "Türkiye\'de yaygın Hanefî vitir Kunut metinleridir. Telaffuz eğitimi için güvenilir insan kaydı kullanılmalıdır; SalahPath bunun için yapay zekâ sesi üretmez."))\n                    .font(.footnote).foregroundStyle(.secondary)\n            }\n        }\n        .navigationTitle(settings.t("Qunūt", "Kunut"))\n    }\n}\n\n// MARK: - Wudu\n\nprivate struct WuduTutorialStep: Identifiable {\n    let id = UUID()\n    let number: Int\n    let image: String?\n    let deTitle: String\n    let trTitle: String\n    let deAction: String\n    let trAction: String\n    let repeatText: String?\n    let hanafiFard: Bool\n}\n\nstruct WuduGuideView: View {\n    @EnvironmentObject private var settings: SettingsStore\n\n    private let steps: [WuduTutorialStep] = [\n        .init(number: 1, image: "wudu_intention", deTitle: "Niyyah & Basmala", trTitle: "Niyet & Besmele", deAction: "Fasse die Absicht für Wudu und beginne mit Bismillāh. Hanafi: Die Absicht ist Sunnah, nicht einer der vier Fard-Bestandteile.", trAction: "Abdest için niyet et ve Bismillâh ile başla. Hanefî: Niyet sünnettir; abdestin dört farzından biri değildir.", repeatText: nil, hanafiFard: false),\n        .init(number: 2, image: "wudu_hands", deTitle: "Hände", trTitle: "Eller", deAction: "Beide Hände bis zu den Handgelenken waschen; Fingerzwischenräume erreichen.", trAction: "İki eli bileklere kadar yıka; parmak aralarına su ulaştır.", repeatText: "3×", hanafiFard: false),\n        .init(number: 3, image: "wudu_mouth", deTitle: "Mund", trTitle: "Ağız", deAction: "Mit der rechten Hand Wasser in den Mund nehmen und gründlich spülen.", trAction: "Sağ elle ağza su alıp iyice çalkala.", repeatText: "3×", hanafiFard: false),\n        .init(number: 4, image: "wudu_nose", deTitle: "Nase", trTitle: "Burun", deAction: "Vorsichtig Wasser in die Nase ziehen und die Nase reinigen.", trAction: "Burnuna nazikçe su verip temizle.", repeatText: "3×", hanafiFard: false),\n        .init(number: 5, image: "wudu_face", deTitle: "Gesicht", trTitle: "Yüz", deAction: "Das ganze Gesicht waschen. Einmal vollständig ist Fard; dreimal entspricht der üblichen Sunnah-Praxis.", trAction: "Yüzün tamamını yıka. Bir kez tam yıkamak farzdır; üç kez yıkamak yaygın sünnet uygulamasıdır.", repeatText: "3×", hanafiFard: true),\n        .init(number: 6, image: "wudu_rightarm", deTitle: "Rechter Arm", trTitle: "Sağ kol", deAction: "Rechten Arm einschließlich Ellenbogen vollständig waschen.", trAction: "Sağ kolu dirsekle birlikte tamamen yıka.", repeatText: "3×", hanafiFard: true),\n        .init(number: 7, image: "wudu_leftarm", deTitle: "Linker Arm", trTitle: "Sol kol", deAction: "Linken Arm einschließlich Ellenbogen vollständig waschen.", trAction: "Sol kolu dirsekle birlikte tamamen yıka.", repeatText: "3×", hanafiFard: true),\n        .init(number: 8, image: "wudu_head", deTitle: "Masah des Kopfes", trTitle: "Başın meshi", deAction: "Mit nassen Händen über den Kopf streichen. Hanafi: Für die Gültigkeit muss mindestens ein Viertel des Kopfes benetzt/gestrichen werden; die verbreitete vollständige Masah wird einmal gemacht.", trAction: "Islak ellerle başı mesh et. Hanefî: Geçerlilik için başın en az dörtte birine ıslaklığın ulaşması gerekir; yaygın tam baş meshi bir kez yapılır.", repeatText: "1×", hanafiFard: true),\n        .init(number: 9, image: "wudu_ears", deTitle: "Ohren", trTitle: "Kulaklar", deAction: "Mit den feuchten Fingern die Innen- und Außenseite der Ohren abwischen. Dies gehört zur Sunnah-Reihenfolge, nicht zu den vier hanafitischen Fard-Bestandteilen.", trAction: "Islak parmaklarla kulakların iç ve dış kısmını mesh et. Bu sünnet sırasındandır; Hanefî abdestin dört farzından biri değildir.", repeatText: "1×", hanafiFard: false),\n        .init(number: 10, image: "wudu_feet", deTitle: "Füße", trTitle: "Ayaklar", deAction: "Zuerst den rechten, dann den linken Fuß einschließlich Knöchel waschen. Wasser muss auch zwischen die Zehen gelangen.", trAction: "Önce sağ, sonra sol ayağı topuklarla birlikte yıka. Parmak aralarına da su ulaştır.", repeatText: "3×", hanafiFard: true)\n    ]\n\n    var body: some View {\n        ScrollView {\n            LazyVStack(spacing: 14) {\n                VStack(alignment: .leading, spacing: 8) {\n                    Label(settings.t("Hanafi · vollständige Lernreihenfolge", "Hanefî · tam öğrenme sırası"), systemImage: "drop.fill").font(.headline)\n                    Text(settings.t("Die vier Fard-Bestandteile sind gesondert markiert. Dreimaliges Waschen ist bei den Waschschritten die Sunnah-Praxis; für die Fard-Gültigkeit ist die vollständige einmalige Waschung der betreffenden Pflichtteile ausreichend.", "Dört farz bölüm ayrıca işaretlidir. Yıkama adımlarını üç kez yapmak sünnet uygulamasıdır; farz olan bölümlerin bir kez tam yıkanması abdestin geçerliliği için yeterlidir."))\n                        .font(.footnote).foregroundStyle(.secondary)\n                }.cardStyle(material: true)\n\n                ForEach(steps) { step in\n                    VStack(alignment: .leading, spacing: 12) {\n                        HStack {\n                            Text("\\(step.number)").font(.headline.bold()).frame(width: 32,height:32).background(Color.blue, in: Circle()).foregroundStyle(.white)\n                            Text(settings.language == .german ? step.deTitle : step.trTitle).font(.title3.bold())\n                            Spacer()\n                            if step.hanafiFard { Text(settings.t("FARD", "FARZ")).font(.caption.bold()).padding(.horizontal,8).padding(.vertical,4).background(Color.orange.opacity(0.18),in:Capsule()) }\n                            if let repeatText = step.repeatText { Text(repeatText).font(.caption.bold()).padding(.horizontal,8).padding(.vertical,4).background(Color.blue.opacity(0.12),in:Capsule()) }\n                        }\n                        if let image = step.image {\n                            Image(image).resizable().scaledToFit().frame(maxWidth:.infinity).frame(maxHeight:220).padding(8).background(Color.blue.opacity(0.045),in:RoundedRectangle(cornerRadius:16)).accessibilityHidden(true)\n                        }\n                        Text(settings.language == .german ? step.deAction : step.trAction).font(.subheadline)\n                    }.cardStyle()\n                }\n\n                VStack(alignment:.leading,spacing:8) {\n                    Text(settings.t("Nach dem Wudu", "Abdestten sonra")).font(.headline)\n                    Text("أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ")\n                        .font(.title3).multilineTextAlignment(.trailing).frame(maxWidth:.infinity,alignment:.trailing)\n                    Text("Eşhedü en lâ ilâhe illallâhü vahdehû lâ şerîke leh, ve eşhedü enne Muhammeden abdühû ve resûlüh.").font(.subheadline.weight(.semibold))\n                    Text(settings.t("Ich bezeuge, dass es keinen Gott außer Allah gibt, ohne Teilhaber, und dass Muhammad Sein Diener und Gesandter ist.", "Allah\'tan başka ilâh olmadığına, O\'nun ortağı bulunmadığına ve Muhammed\'in O\'nun kulu ve elçisi olduğuna şahitlik ederim.")).font(.footnote).foregroundStyle(.secondary)\n                }.cardStyle()\n\n                VStack(alignment:.leading,spacing:6) {\n                    Link("Diyanet · Abdest nasıl alınır?", destination: URL(string:"https://kurul.diyanet.gov.tr/tr/fetva/abdest-nedir-ve-nasil-alinir/0193c42d-4493-7cd5-0d48-874d6be1a7d3")!)\n                    Link("Diyanet · Abdestin farzları", destination: URL(string:"https://kurul.diyanet.gov.tr/tr/fetva/mezhepler-arasinda-abdestin-farzlari-konusunda-farklilik/0193c42d-44c2-71a2-18f9-9a29fcdbaa43")!)\n                }.cardStyle(material:true)\n            }.padding()\n        }\n        .navigationTitle(settings.t("Wudu komplett", "Abdest tamamen"))\n        .navigationBarTitleDisplayMode(.inline)\n    }\n}\n\n'


root = Path(".")
assets_root = root / "SalahZeit" / "Assets.xcassets"
for name, encoded in ASSETS.items():
    d = assets_root / f"{name}.imageset"
    d.mkdir(parents=True, exist_ok=True)
    (d / f"{name}.jpg").write_bytes(base64.b64decode(encoded))
    (d / "Contents.json").write_text(json.dumps({
        "images": [{"filename": f"{name}.jpg", "idiom": "universal", "scale": "1x"}],
        "info": {"author": "xcode", "version": 1}
    }, ensure_ascii=False), encoding="utf-8")

p = root / "SalahZeit" / "Views" / "GuideView.swift"
s = p.read_text(encoding="utf-8")
start = s.index("// MARK: - Prayer guide")
end = s.index("// MARK: - Terms")
replacement = Path("/tmp/v35_block.swift").read_text(encoding="utf-8") if Path("/tmp/v35_block.swift").exists() else BLOCK
s = s[:start] + replacement + "\n// MARK: - Terms\n" + s[end + len("// MARK: - Terms"):]
# Add exact plan link to the learning hub if absent
needle = 'NavigationLink { RakatOverviewView() } label: {\n                    Label(settings.t("Fard, Sunnah & Witr", "Farz, sünnet ve vitir"), systemImage: "list.number")\n                }'
if needle in s and 'HanafiPrayerPlanView()' not in s[:start]:
    s = s.replace(needle, needle + '\n                NavigationLink { HanafiPrayerPlanView() } label: {\n                    Label(settings.t("Gebetsablauf exakt", "Namaz akışı ayrıntılı"), systemImage: "checklist")\n                }', 1)
p.write_text(s, encoding="utf-8")

# version
bp = root / "scripts" / "build_unsigned_ipa.sh"
b = bp.read_text(encoding="utf-8")
b = b.replace('MARKETING_VERSION="3.4"', 'MARKETING_VERSION="3.5"')
b = b.replace('CURRENT_PROJECT_VERSION="7"', 'CURRENT_PROJECT_VERSION="8"')
bp.write_text(b, encoding="utf-8")
print("SalahPath v3.5 patch applied")